import re

_DURATION_RE = re.compile(r"[0-9]+[hmsHMS](\s+[0-9]+[hmsHMS])*")
_PART_RE = re.compile(r"([0-9]+)([hmsHMS])")
_UNIT_SECONDS = {"h": 3600, "m": 60, "s": 1}
_UNIT_ORDER = {"h": 0, "m": 1, "s": 2}


def parse_duration(s: str) -> int:
    value = s.strip()
    if not value:
        raise ValueError("empty duration string")
    if _DURATION_RE.fullmatch(value) is None:
        raise ValueError("invalid duration string")

    total = 0
    last_order = -1

    for match in _PART_RE.finditer(value):
        amount = int(match.group(1))
        unit = match.group(2).lower()
        order = _UNIT_ORDER[unit]

        if order <= last_order:
            raise ValueError("units must be unique and appear in h, m, s order")

        last_order = order
        total += amount * _UNIT_SECONDS[unit]

    return total

