def summarize_ranges(nums: list[int]) -> str:
    nums = sorted(set(nums))
    if not nums:
        return ""

    parts = []
    i = 0
    n = len(nums)

    while i < n:
        j = i
        while j + 1 < n and nums[j + 1] == nums[j] + 1:
            j += 1

        run_length = j - i + 1
        if run_length >= 3:
            parts.append(f"{nums[i]}..{nums[j]}")
        else:
            parts.extend(str(nums[k]) for k in range(i, j + 1))

        i = j + 1

    return ",".join(parts)
